const MENU_BUTTON_TEXT = document.getElementById("hideNavbarButtonText");
const MENU_BUTTON = document.getElementById("navbarToggleButton");
const NAV_MENU = document.getElementById("navigationMenu");





// ========================================
// THEME PANEL
// ========================================

document.addEventListener("click", (event) => {

    const startButton = event.target.closest("#start-button");
    const themePanel = document.getElementById("theme-panel");

    if (!themePanel) return;


    // Start button clicked
    if (startButton) {

        event.stopPropagation();

        themePanel.classList.toggle("open");

        return;
    }


    // Theme option clicked
    const themeOption = event.target.closest(".theme-option");

    if (themeOption) {

        const theme = themeOption.dataset.theme;

        console.log("Selected theme:", theme);
        localStorage.setItem("theme", theme);
        

        

        if (theme === "classic") {
            document.body.classList.add("classic-theme");
        }
        else if (theme === "winter") {
            document.body.classList.add("winter-theme");
        }
        else if (theme === "fortnite") {
            document.body.classList.add("winter-theme");
        }
        else if (theme === "halo") {
            document.body.classList.add("winter-theme");
        }
        else if (theme === "minecraft") {
            document.body.classList.add("winter-theme");
        }

        return;
    }


    // Click anywhere outside the panel
    if (!themePanel.contains(event.target)) {

        themePanel.classList.remove("open");

    }

});


MENU_BUTTON.addEventListener("click", function () {

    if (NAV_MENU.style.display === "block") {

        MENU_BUTTON_TEXT.innerHTML = "Menu >";
        NAV_MENU.style.display = "none";

    } else {

        MENU_BUTTON_TEXT.innerHTML = "Hide >";
        NAV_MENU.style.display = "block";

    }

});


window.addEventListener("resize", function () {

    if (window.innerWidth > 650) {

        MENU_BUTTON_TEXT.innerHTML = "Hide >";
        NAV_MENU.style.display = "block";

    }

    if (window.innerWidth < 650) {

        MENU_BUTTON_TEXT.innerHTML = "Menu >";
        NAV_MENU.style.display = "none";

    }

});



function toggleSchedule() {
    document
        .getElementById("schedule-widget")
        .classList.toggle("open");
}
